return array (
  'title' => '10 पीडीएफ वर्कफ़्लो हैक्स जो दूर-दराज के श्रमिकों के हर सप्ताह 3+ घंटे बचाते हैं',
  'description' => 'अपने पीडीएफ वर्कफ़्लो को अनुकूलित करें और उत्पादकता के घंटे पुनः प्राप्त करें। कंप्रेशन, क्लाउड टूल, टेम्प्लेट, ओसीआर और ऑटोमेशन सहित दूरस्थ श्रमिकों के लिए 10 कार्रवाई योग्य हैक खोजें।',
  'main-heading' => '10 पीडीएफ वर्कफ़्लो हैक्स जो दूर-दराज के श्रमिकों के हर सप्ताह 3+ घंटे बचाते हैं',
  'intro-heading' => 'रिमोट वर्क में छिपा हुआ समय सिंक',
  'intro-p1' => 'दूरस्थ श्रमिकों का मूल्यांकन अक्सर आउटपुट पर किया जाता है, लेकिन उनके समय का एक आश्चर्यजनक हिस्सा दस्तावेज़ प्रबंधन प्रक्रियाओं में गायब हो जाता है जो धीमी और आवश्यकता से अधिक मैन्युअल होती हैं। किसी फ़ाइल को डाउनलोड करना, उसे संसाधित करना, उसे कहीं और अपलोड करना, प्रतिक्रिया की प्रतीक्षा करना और चक्र को दोहराने में वास्तविक काम जैसा कुछ भी उत्पन्न किए बिना प्रति सप्ताह घंटों का समय लगता है।',
  'intro-p2' => 'इस गाइड में दस हैक्स दूरस्थ कार्य सेटिंग्स में सबसे आम पीडीएफ वर्कफ़्लो अक्षमताओं को संबोधित करते हैं। प्रत्येक में सामान्य दस्तावेज़ प्रबंधन आवृत्ति के आधार पर प्रति सप्ताह बचाए गए समय का यथार्थवादी अनुमान शामिल होता है। उनमें से आधे को भी क्रियान्वित करने से सार्थक समय की प्राप्ति हो जाती है।',
  'hack1-heading' => '1. एक-क्लिक पीडीएफ प्रिंटर सेट करें (प्रति सप्ताह 20 मिनट बचाएं)',
  'hack1-p1' => 'किसी भी एप्लिकेशन से पीडीएफ बनाने में आम तौर पर कई मेनू के माध्यम से नेविगेट करना शामिल होता है: फ़ाइल, फिर प्रिंट, फिर प्रिंटर को पीडीएफ विकल्प में बदलना, फिर पुष्टि करना। जो व्यक्ति प्रति सप्ताह 20 से 30 पीडीएफ बनाता है, उसके लिए वह छह-क्लिक अनुक्रम लगभग 20 मिनट के मेनू नेविगेशन तक जुड़ जाता है।',
  'hack1-p2' => 'विंडोज़ पर, Microsoft Print to PDF को अपने डिफ़ॉल्ट प्रिंटर के रूप में सेट करना और Ctrl+P फिर Enter को दो-कीस्ट्रोक शॉर्टकट के रूप में उपयोग करना इसे कुछ सेकंड में कम कर देता है। मैक पर, सिस्टम प्राथमिकताओं के माध्यम से पीडीएफ के रूप में निर्यात कार्रवाई के लिए एक कीबोर्ड शॉर्टकट सेट करने से उतना ही समय बचता है। किसी भी प्लेटफ़ॉर्म पर, मेनू के बजाय कीबोर्ड शॉर्टकट का उपयोग करने की आदत से एक सप्ताह में सार्थक समय की बचत होती है।',
  'hack2-heading' => '2. पीडीएफ टूल्स को सीधे क्लाउड स्टोरेज से कनेक्ट करें (प्रति सप्ताह 30 मिनट बचाएं)',
  'hack2-p1' => 'पीडीएफ वर्कफ़्लो में सबसे आम अक्षमता मैन्युअल डाउनलोड-प्रक्रिया-अपलोड चक्र है। कोई व्यक्ति Google ड्राइव से एक फ़ाइल डाउनलोड करता है, एक ऑनलाइन टूल खोलता है, इसे अपलोड करता है, इसे संसाधित करता है, परिणाम डाउनलोड करता है, और फिर इसे वापस ड्राइव पर अपलोड करता है। पीडीएफटूल्स सीधे Google ड्राइव और ड्रॉपबॉक्स एकीकरण का समर्थन करता है, जो मध्यवर्ती डाउनलोड और पुनः अपलोड चरणों को पूरी तरह से समाप्त कर देता है। __COMPRESS_LINK__, __MERGE_LINK__, और __WORD_LINK__ सभी सीधे क्लाउड स्टोरेज आयात और निर्यात का समर्थन करते हैं।',
  'hack3-heading' => '3. केवल वही पेज निकालें जिनकी आपको वास्तव में आवश्यकता है (प्रति सप्ताह 25 मिनट बचाएं)',
  'hack3-p1' => 'किसी सहकर्मी को, जिसे केवल 5 विशिष्ट पृष्ठों की आवश्यकता है, पूरी 80-पृष्ठ की रिपोर्ट भेजने से उनका भी उतना ही समय बर्बाद होता है जितना आपका। प्रासंगिक पृष्ठों को निकालना और केवल उन्हें भेजना अधिक पेशेवर है, एक छोटी फ़ाइल तैयार करता है जो इनबॉक्स को अवरुद्ध नहीं करता है, और दो मिनट से भी कम समय लेता है।',
  'hack3-p2' => '__SPLITTER_LINK__ पेज निष्कर्षण को सेकंडों में संभाल लेता है। दूरदराज के श्रमिकों के लिए जो नियमित रूप से विभिन्न हितधारकों के साथ बड़े दस्तावेज़ों के अनुभाग साझा करते हैं, यह एक सामयिक कार्य के बजाय दस्तावेज़ तैयारी वर्कफ़्लो का एक मानक हिस्सा बन जाता है।',
  'hack4-heading' => '4. आवर्ती दस्तावेज़ों के लिए भरने योग्य पीडीएफ टेम्पलेट का उपयोग करें (प्रति सप्ताह 45 मिनट बचाएं)',
  'hack4-p1' => 'कोई भी दस्तावेज़ जो एक सुसंगत संरचना का पालन करता है और बार-बार बनाया जाता है, एक भरने योग्य पीडीएफ टेम्पलेट के लिए उम्मीदवार है। प्रोजेक्ट स्थिति रिपोर्ट, क्लाइंट इनवॉइस, साप्ताहिक टाइमशीट, मीटिंग एजेंडा टेम्पलेट और ऑनबोर्डिंग चेकलिस्ट सभी सामान्य उदाहरण हैं।',
  'hack4-p2' => 'एक भरने योग्य पीडीएफ टेम्पलेट आपको दस्तावेज़ संरचना को हर बार पुनर्निर्माण किए बिना, दिनांक, ग्राहक नाम, मात्रा और प्रोजेक्ट नाम जैसे परिवर्तनीय फ़ील्ड अपडेट करने देता है। एक फ्रीलांसर के लिए जो कई ग्राहकों के लिए चालान तैयार करता है, एक अच्छा टेम्पलेट प्रति चालान 10 से 15 मिनट के पुन: स्वरूपण को समाप्त कर देता है। कई ग्राहकों के साथ एक महीने में, इसका मतलब एक घंटे से अधिक की बचत होती है।',
  'hack5-heading' => '5. स्कैन की गई पीडीएफ को ओसीआर के साथ खोजने योग्य बनाएं (प्रति सप्ताह 20 मिनट बचाएं)',
  'hack5-p1' => 'स्कैन किए गए दस्तावेज़ केवल-छवि पीडीएफ के रूप में आते हैं जहां पाठ को खोजा, चयनित या कॉपी नहीं किया जा सकता है। 60-पृष्ठ के स्कैन किए गए अनुबंध में एक विशिष्ट खंड ढूंढने के लिए प्रत्येक पृष्ठ पर मैन्युअल रूप से स्क्रॉल करने की आवश्यकता होती है। ओसीआर स्कैन की गई छवियों को वास्तविक पाठ में परिवर्तित करता है, जिससे संपूर्ण दस्तावेज़ खोजने योग्य और चयन योग्य हो जाता है।',
  'hack5-p2' => 'जब आप Google डॉक्स में एक पीडीएफ खोलते हैं तो Google ड्राइव स्वचालित रूप से OCR निष्पादित कर सकता है। __WORD_LINK__ रूपांतरण के दौरान पीडीएफ से पाठ भी निकालता है, जिससे सामग्री संपादन और खोज के लिए सुलभ हो जाती है। एक बार जब स्कैन किए गए दस्तावेज़ को OCR के साथ संसाधित किया जाता है, तो Ctrl+F के साथ उस सामग्री को ढूंढने में कुछ सेकंड लगते हैं, जिसे स्क्रॉल करने में कुछ मिनट लगते हैं।',
  'hack6-heading' => '6. मुद्रण के बजाय डिजिटल रूप से एनोटेट करें (प्रति सप्ताह 25 मिनट बचाएं)',
  'hack6-p1' => 'किसी दस्तावेज़ को पेन से चिह्नित करने के लिए प्रिंट करना, फिर उसे स्कैन करना और वापस भेजना, एक वर्कफ़्लो है जिसे वर्षों पहले डिजिटल एनोटेशन टूल द्वारा बदल दिया गया था। एडोब एक्रोबैट रीडर (फ्री), ऐप्पल बुक्स, माइक्रोसॉफ्ट एज और अधिकांश आधुनिक पीडीएफ रीडर में एनोटेशन टूल शामिल हैं जो सीधे पीडीएफ में टिप्पणियां, हाइलाइट्स और मार्कअप जोड़ते हैं।',
  'hack6-p2' => 'डिजिटल एनोटेशन भी खोजने योग्य, प्रतिवर्ती हैं और आसानी से साझा किए जा सकते हैं। एनोटेटेड पीडीएफ में एक टिप्पणी थ्रेड हस्तलिखित मार्जिन नोट्स के स्कैन की तुलना में अधिक उपयोगी है, क्योंकि टिप्पणियों को पुनर्मुद्रण के बिना संबोधित और हल किया जा सकता है।',
  'hack7-heading' => '7. एक साथ कई पीडीएफ को बैच प्रोसेस करें (प्रति सप्ताह 30 मिनट बचाएं)',
  'hack7-p1' => 'पीडीएफ के एक सेट को एक-एक करके संपीड़ित करने, नाम बदलने या परिवर्तित करने में लगभग उतना ही समय लगता है जितना उन्हें बैच में करने में लगता है, सिवाय इसके कि आपको प्रत्येक फ़ाइल के लिए प्रक्रिया को मैन्युअल रूप से दोहराना होगा। अधिकांश पेशेवर पीडीएफ उपकरण बैच संचालन का समर्थन करते हैं जो एक ही प्रक्रिया में कई फाइलों को संभालते हैं।',
  'hack7-p2' => 'दूरस्थ श्रमिकों के लिए जो नियमित रूप से एक ही दस्तावेज़ प्रकार के बैच प्राप्त करते हैं, जैसे व्यय रसीदें, हस्ताक्षरित दस्तावेज़, या विक्रेता चालान, प्रत्येक सप्ताह की शुरुआत में एक बैच संपीड़न दिनचर्या स्थापित करने से पूरे सप्ताह प्रत्येक फ़ाइल को व्यक्तिगत रूप से संभालने का समय बचता है।',
  'hack8-heading' => '8. मीटिंग में पीडीएफ साझा करने के लिए क्यूआर कोड का उपयोग करें (प्रति सप्ताह 15 मिनट बचाएं)',
  'hack8-p1' => 'चैट में डाउनलोड लिंक चिपकाकर दूरस्थ बैठकों में दस्तावेज़ वितरित करने में समय लगता है, और लिंक छूट सकते हैं या मोबाइल उपकरणों पर क्लिक करना मुश्किल हो सकता है। वीडियो कॉल के दौरान स्क्रीन पर प्रदर्शित एक क्यूआर कोड हर किसी को अपने फोन के कैमरे को स्क्रीन पर इंगित करके दस्तावेज़ को तुरंत डाउनलोड करने की अनुमति देता है।',
  'hack8-p2' => 'पीडीएफ को Google ड्राइव पर अपलोड करें, किसी भी मुफ्त क्यूआर कोड जनरेटर का उपयोग करके साझा करने योग्य लिंक की ओर इशारा करते हुए एक क्यूआर कोड उत्पन्न करें, और इसे अपनी प्रस्तुति स्लाइड में एम्बेड करें या चैट में साझा करें। इससे यह सुनिश्चित करने की झंझट दूर हो जाती है कि हर किसी के पास दस्तावेज़ का नवीनतम संस्करण हो।',
  'hack9-heading' => '9. अपनी भेजें चेकलिस्ट में एक संपीड़न चरण रखें (प्रति सप्ताह 15 मिनट बचाएं)',
  'hack9-p1' => 'दूर-दराज के कर्मचारी ईमेल पर जो समय बिताते हैं उसका एक बड़ा हिस्सा अटैचमेंट बाउंस नोटिफिकेशन और फॉलो-अप ईमेल द्वारा उन फ़ाइलों को दोबारा भेजने के कारण होता है जो बहुत बड़ी थीं। किसी भी पीडीएफ को संलग्न करने से पहले एक त्वरित संपीड़न कदम को आदत में शामिल करने से इनमें से अधिकांश देरी को रोका जा सकता है।',
  'hack9-p2' => 'इस आदत में 90 सेकंड से भी कम समय लगता है: __COMPRESS_LINK__ खोलें, फ़ाइल अपलोड करें, संपीड़ित संस्करण डाउनलोड करें, उसे संलग्न करें। ईमेल बाउंस होने और दोबारा भेजने में लगने वाले समय की तुलना में, यह रूटीन पहले उपयोग पर ही भुगतान कर देता है। अनुलग्नक सीमा पर अधिक विवरण के लिए, __EMAIL_LINK__ देखें।',
  'hack10-heading' => '10. बिना कोड टूल के साथ आवर्ती पीडीएफ कार्यों को स्वचालित करें (प्रति सप्ताह 60+ मिनट बचाएं)',
  'hack10-p1' => 'महत्वपूर्ण दस्तावेज़ मात्रा को संभालने वाले दूरस्थ श्रमिकों के लिए सबसे शक्तिशाली दक्षता लाभ स्वचालन है। जैपियर और मेक (पूर्व में इंटेग्रोमैट) जैसे उपकरण अन्य अनुप्रयोगों में घटनाओं के आधार पर पीडीएफ संचालन को स्वचालित रूप से ट्रिगर कर सकते हैं।',
  'hack10-p2' => 'व्यावहारिक उदाहरणों में शामिल हैं: जब कोई फॉर्म सबमिशन आता है, तो स्वचालित रूप से डेटा को एक स्वरूपित पीडीएफ रिपोर्ट में संकलित करें और इसे निर्दिष्ट फ़ोल्डर में सहेजें। जब कोई अनुबंध ई-हस्ताक्षर उपकरण में पूरा हो जाता है, तो स्वचालित रूप से इसे संपीड़ित करें और इसे प्रोजेक्ट फ़ोल्डर में संग्रहीत करें। जब कोई रसीद ईमेल द्वारा आती है, तो उसे स्वचालित रूप से पीडीएफ अनुलग्नक के रूप में निकालें और व्यय ट्रैकिंग फ़ोल्डर में जोड़ें।',
  'hack10-p3' => 'इनमें से प्रत्येक ऑटोमेशन को शुरू में स्थापित होने में 20 से 45 मिनट लगते हैं लेकिन हर बार चलने पर कई मिनट की बचत होती है। दैनिक या साप्ताहिक होने वाली आवर्ती प्रक्रियाओं के लिए, निवेश आमतौर पर पहले दो सप्ताह के भीतर वापस भुगतान कर देता है।',
  'conclusion-heading' => 'निष्कर्ष',
  'conclusion-p1' => 'दूरस्थ कार्य में दस्तावेज़ प्रबंधन की अक्षमता काफी हद तक अदृश्य है क्योंकि यह छोटी-छोटी वृद्धियों में होती है। कोई भी पीडीएफ कार्य बहुत अधिक समय बर्बाद करने जैसा नहीं लगता। लेकिन एक हफ्ते में जमा हुई रकम कुछ और ही कहानी बयां करती है। इस गाइड में हैक्स को लागू करने से उस संचय के सबसे सामान्य स्रोतों का पता चलता है।',
  'conclusion-p2' => 'उन दो या तीन से शुरुआत करें जो आपके सबसे बड़े वर्तमान समस्या बिंदुओं से मेल खाते हों और वहां से निर्माण करें। PDFTools के उपकरण, जिनमें __COMPRESS_LINK__, __SPLITTER_LINK__, और __MERGE_LINK__ शामिल हैं, सीधे क्लाउड स्टोरेज एकीकरण हैक का समर्थन करते हैं और पंजीकरण के बिना उपयोग करने के लिए स्वतंत्र हैं।',
  'faq-heading' => 'अक्सर पूछे जाने वाले प्रश्नों',
  'faq1-q' => 'इनमें से कौन सा हैक सेटअप समय पर सबसे अच्छा रिटर्न देता है?',
  'faq1-a' => 'क्लाउड स्टोरेज एकीकरण लगभग बिना किसी सेटअप के तुरंत समय बचाता है। भरने योग्य टेम्पलेट और ओसीआर हैक्स का सेटअप थोड़ा लंबा होता है, लेकिन आवर्ती दस्तावेज़ प्रकारों को संभालने वाले श्रमिकों के लिए प्रति सप्ताह सबसे बड़ी बचत होती है। ऑटोमेशन हैक में सेटअप का समय सबसे लंबा है लेकिन चल रही बचत के लिए उच्चतम सीमा है।',
  'faq2-q' => 'क्या ये हैक टीमों के साथ-साथ व्यक्तियों के लिए भी काम करते हैं?',
  'faq2-a' => 'हाँ। क्लाउड स्टोरेज इंटीग्रेशन और बैच प्रोसेसिंग हैक टीमों के लिए विशेष रूप से प्रभावी हैं क्योंकि वे सुसंगत, साझा वर्कफ़्लो बनाते हैं जो केवल उन्हें सेट करने वाले व्यक्ति के बजाय सभी को लाभान्वित करते हैं। साझा टेम्पलेट और मानक एनोटेशन प्रथाएं पूरी टीम का समय बचाती हैं।',
);
